export default async function reserve(
  { requestId, email, parsed, calendarId, acknowledge, resolution },
  ctx,
) {
  if (
    !/^[A-Za-z0-9_-]{1,100}$/.test(requestId) ||
    !email ||
    !parsed?.start ||
    !Number.isFinite(Date.parse(parsed.start))
  )
    throw Error("Valid request ID, email and date required");
  const key = "tool-appointment:" + requestId,
    start = new Date(parsed.start).toISOString(),
    event = {
      summary: "Event title with " + email,
      description: "Event description",
      start: { dateTime: start },
      end: { dateTime: new Date(Date.parse(start) + 3600000).toISOString() },
    };
  let state = await ctx.state.get(key);
  if (state && (state.email !== email || state.start !== start)) throw Error("Request changed");
  if (state?.pending) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + key);
    if (resolution === "confirmed") {
      state.pending = false;
      state.done = true;
    } else state.pending = false;
    await ctx.state.set(key, state);
  }
  if (state?.done) return { write: false, key, event, calendarId };
  state = { email, start, pending: true, done: false };
  await ctx.state.set(key, state);
  return { write: true, key, event, calendarId };
}

