export default async function confirm({ key, eventId }, ctx) {
  if (!eventId) throw Error("Unknown calendar result");
  const state = await ctx.state.get(key);
  if (!state?.pending) throw Error("Missing pending write");
  state.pending = false;
  state.done = true;
  state.eventId = eventId;
  await ctx.state.set(key, state);
  return { body: { text: "L’evento è stato creato con successo", eventId } };
}

